import re
from dataclasses import dataclass, field
from typing import Optional

# Release headings: "## [2.4.0] - 2024-05-02". The "## [Unreleased]" heading has no date.
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# HTML comments, on one line or spanning several. Whitespace that a removed comment
# leaves at the end of its line is dropped too (the optional trailing whitespace
# is only consumed when the comment ends the line).
COMMENT = re.compile(
    r"(?P<lead>[ \t]*)<!--.*?-->(?P<trail>[ \t]*)(?=\r?\n|\Z)|<!--.*?-->",
    re.DOTALL,
)


def _strip_comments(match):
    if match.group("trail") is None:
        # Comment is followed by more text on the same line: keep one separator.
        return ""
    if match.group("lead") is None:
        return ""
    return ""


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def _remove_comments(text):
    # Simple, explicit version: drop each comment; if it sits at the end of its
    # line, also drop the spaces that preceded it on that line.
    out = []
    pos = 0
    for match in re.finditer(r"[ \t]*<!--.*?-->[ \t]*", text, re.DOTALL):
        out.append(text[pos:match.start()])
        rest = text[match.end():]
        ends_line = rest == "" or re.match(r"\r?\n", rest) is not None
        if ends_line:
            out.append("")
        else:
            # Mid-line comment: keep the separator on one side only.
            lead = re.match(r"[ \t]*", text[match.start():]).group(0)
            out.append(lead if lead else "")
            if not lead and match.group(0).endswith((" ", "\t")):
                out.append(" ")
        pos = match.end()
    out.append(text[pos:])
    return "".join(out)


def parse_changelog(text):
    releases = []
    current = None
    for line in _remove_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                raise ValueError(f"malformed release heading: {line!r}")
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _normalize_body(lines):
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] == "":
                continue
            out.append("")
        else:
            out.append(line)
    while out and out[-1] == "":
        out.pop()
    while out and out[0] == "":
        out.pop(0)
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = _normalize_body(release.body)
            title = f"# {release.version} ({release.date})" if release.date else f"# {release.version}"
            return f"{title}\n\n{body}\n"
    raise LookupError(version)

